const STRICT_ZERO_ERROR_RULES = `CRITICAL RULES FOR ZERO ERRORS for this document profile: 1) Strict Syntactic Compliance — return only valid, parseable JSON matching the supplied strict JSON schema. Never output prose before or after JSON. 2) Absolute Character Fidelity — transcribe visible text exactly as written. Never auto-correct spelling mistakes, typos, punctuation, capitalization, grammar, names, identifiers, dates, amounts or codes. 3) Zero Hallucination & Guessing — never infer a blurry, smudged, clipped, obscured or unsupported character, number or digit. Use null for an unreadable structured value and use [illegible] only inside full transcription where unreadable visible text must be represented. 4) Language Integrity — preserve the exact native language and script. Never translate. 5) Zero Conversational Filler — output structured extraction only. Preserve all active document-specific canonical labels, validation rules and field boundaries. The original image is primary evidence; local OCR is supporting evidence only and may be wrong.`;
const STRICT_TEXT_DOCUMENT_RULES = `For General Document, Letter / Memo and Report / Statement only: operate as a zero-error OCR transcription and data-extraction engine. Preserve every visible character exactly as written. Do not auto-correct spelling, punctuation, grammar or capitalization. Preserve the original language and script and never translate. Never guess unreadable characters. If text is unreadable, use [illegible] in transcription and use null for an unreadable structured value rather than fabricating it. Treat the default body transcription as plain text rather than Markdown. Extract the visible title, headings, body content, key/value pairs and tables in reading order. Record unreadable or structurally uncertain regions in uncertain_regions. Do not add conversational filler.`;
function isStrictTextDocumentType(type){return STRICT_TEXT_DOCUMENT_TYPES.has(String(type||""))}
function isStrictZeroErrorDocumentType(type){return STRICT_ZERO_ERROR_DOCUMENT_TYPES.has(String(type||""))}
