function buildStrictTextResult(result,type){
  const key_value_pairs={};
  for(const section of result?.sections||[])for(const f of section?.fields||[]){const k=String(f?.label||"").trim();if(k&&!Object.prototype.hasOwnProperty.call(key_value_pairs,k))key_value_pairs[k]=String(f?.value||"").trim()||null}
  const headings=[];const seen=new Set();for(const section of result?.sections||[]){const h=String(section?.name||"").trim();const k=h.toLowerCase();if(h&&!seen.has(k)){seen.add(k);headings.push(h)}}
  const tables=(result?.tables||[]).map(t=>({columns:(t?.headers||[]).map(x=>String(x??"")),rows:(t?.rows||[]).map(r=>(Array.isArray(r)?r:[r]).map(x=>String(x??"")))}));
  const anomalies=(result?.uncertain_regions||[]).map(x=>String(x?.description||x?.visible_text||"Unreadable or uncertain region detected")).filter(Boolean);
  const confidences=[];for(const section of result?.sections||[])for(const f of section?.fields||[]){const n=Number(f?.confidence);if(Number.isFinite(n))confidences.push(n)}for(const x of result?.uncertain_regions||[]){const n=Number(x?.confidence);if(Number.isFinite(n))confidences.push(n)}
  const avg=confidences.length?confidences.reduce((a,b)=>a+b,0)/confidences.length:0.85;
  const rawTitle=String(result?.document?.title||"").trim();
  return{metadata:{detected_language:String(result?.document?.language||"unknown"),document_type:type,overall_confidence:confidenceBand(avg)},extracted_data:{title:rawTitle||null,headings,body_content:String(result?.full_transcription||"").replace(/\r/g,"").trim(),key_value_pairs,tables},errors_or_anomalies:[...new Set(anomalies)]}
}

